"use strict";
const eraPosters=[
 {id:'anime',from:1999,title:'放学以后，动漫见！',subtitle:'猜测楼 / 追番讨论 / 不看未来答案',image:'anime',action:'anime'},
 {id:'magazine',from:2002,title:'手机DIY · 杂志封底',subtitle:'彩铃、壁纸、MP3、短信小广告',image:'magazine',action:'magazine'},
 {id:'games',from:2003,title:'今晚，江湖见！',subtitle:'掌中游戏厅 · 再来最后一局',image:'games',action:'games'},
 {id:'ringtone',from:2006,title:'秋天不回来 · 彩铃记忆',subtitle:'那些年，手机响起的旋律',image:'ringtone',action:'ringtone'}
];
function postersForYear(){return eraPosters.filter(p=>p.from<=Number(year()));}
function posterStrip(context='home'){return `<section class="era-poster-wall"><header><h2>那年，满屏都是这些海报</h2><div><button data-poster-room>翻开年代画报</button>${Number(year())<2006?'<button data-poster-era="2006">去2006年看彩铃海报</button>':''}</div></header><div class="era-poster-row">${postersForYear().map(p=>`<button class="era-poster-card" data-era-poster="${p.id}"><img loading="lazy" src="images/posters/${p.image}.jpg" alt="${escapeHTML(p.title)}怀旧创作海报"><span><b>${p.title}</b><small>${p.subtitle}</small></span></button>`).join('')}</div><small class="poster-footnote">原创怀旧画报 · AI辅助绘制 · 非历史原刊或品牌官方广告</small></section>`;}
function openPosterRoom(){navigate({type:'posters',name:'年代画报与彩铃',url:'archaeo://posters'});}
function renderPosterRoom(){return `<section class="poster-room"><header><small>RINGBACK TONES / MAGAZINE / WALLPAPER</small><h1>手机一响，整个年代都回来了。</h1><p>翻翻杂志，存一张壁纸，想起那首听过很多遍的歌。</p><nav><button data-action="home">时光首页</button><button data-memory-gallery>美女壁纸 / 图文</button><button data-world-channel="music">打开随身听</button><button data-phone-lab>进入旧手机</button></nav></header>${posterStrip('room')}<section class="ringtone-chart"><header><h2>彩铃记忆点播台</h2><span>歌曲资料与正版平台入口</span></header>${Number(year())>=2006?`<article><span class="ringtone-rank">01</span><div><h3>秋天不回来 <small>王强 · 2006彩铃记忆</small></h3><p>不是每一通电话都记得打给了谁，但有些旋律，一响就想起了那时候。</p><a href="https://tv.cctv.com/2018/12/16/VIDEW56WwKAMSwFzClIi7tle181216.shtml" target="_blank" rel="noopener noreferrer">央视正版演唱页面 ↗</a><a href="https://ent.cctv.com/20080606/104144.shtml" target="_blank" rel="noopener noreferrer">歌曲与彩铃年代资料 ↗</a></div><button data-era-poster="ringtone">看海报</button></article>`:'<p>这台彩铃记忆点播机从2006年开始。<button data-poster-era="2006">回到2006年 →</button></p>'}<p class="ringtone-note">不提供商业原曲录音或真实彩铃订购；正版页面在新窗口打开。站内随身听使用原创合成配乐与公版旋律演奏。</p></section><div class="poster-extra"><button data-phone-gallery>把图文装进口袋</button><button data-ad-magazine>编辑短信，发送体验代码</button><button data-capture-view>给这一页留张截图</button></div></section>`;}
function openEraPoster(id){const p=eraPosters.find(x=>x.id===id);if(!p)return;dialog(p.title,`<div class="poster-detail"><img src="images/posters/${p.image}.jpg" alt="${escapeHTML(p.title)}怀旧创作海报"><p>AI辅助怀旧创作 · 非历史原刊 / 官方广告</p><div>${p.action==='anime'?'<button data-anime-club>进入动漫放映社</button>':p.action==='games'?'<button data-world-channel="games">进入游戏厅</button>':p.action==='ringtone'?'<button data-poster-room>打开彩铃点播台</button>':'<button data-ad-magazine>翻开杂志封底</button>'}<button data-phone-gallery>去旧手机里看图</button></div></div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-era-poster],[data-poster-room],[data-poster-era]');if(!b)return;e.preventDefault();if(b.dataset.eraPoster)return openEraPoster(b.dataset.eraPoster);if(b.dataset.posterEra==='2006'){applyDate('2006'+date.slice(4));openPosterRoom();return;}if(b.hasAttribute('data-poster-room')){$('#modal').close();openPosterRoom();}});
